use verus::prelude::*;

verus! {

    /// Returns the index of the first (leftmost) minimum element in `a`.
    /// Requires: a.len() > 0
    /// Ensures:
    ///   0 <= res < a.len()
    ///   ∀ j < a.len(): a[res] <= a[j]
    ///   ∀ j < res:       a[j] >  a[res]
    pub fn get_mini(a: &Slice<i32>) -> usize {
        // precondition
        requires(a.len() > 0);

        // postconditions
        ensures(|res: usize| res < a.len());
        ensures(|res: usize| forall(|j: usize| j < a.len() ==> a@res <= a@j));
        ensures(|res: usize| forall(|j: usize| j < res    ==> a@j >  a@res));

        let n = a.len();
        let mut res: usize = 0;     // current best index of the minimum so far
        let mut i:   usize = 1;     // scan index

        while i < n
            invariant(res < n);
            invariant(i <= n);
            // up to (but not including) i, `res` is the index of the minimum
            invariant(forall(|j: usize| j < i ==> a@res <= a@j));
            // to the left of res, everything is strictly greater than a[res]
            invariant(forall(|j: usize| j < res ==> a@j > a@res));
            decreases(n - i);
        {
            if a@i < a@res {
                res = i;
            }
            i += 1;
        }

        // At this point i == n, and the invariants guarantee the
        // postconditions for res.
        res
    }
}